package com.resqnow1.app.updates;

import org.junit.Test;import org.junit.Rule;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
import java.io.File;import java.io.FileOutputStream;import java.io.IOException;import java.net.HttpURLConnection;import java.net.InetSocketAddress;import java.net.URL;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.security.MessageDigest;import java.util.Map;import java.util.concurrent.atomic.AtomicInteger;import java.util.concurrent.atomic.AtomicReference;

public class UpdateDownloaderTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 private static final byte[] BYTES="0123456789abcdef".getBytes(StandardCharsets.US_ASCII);
 private static String sha(byte[] bytes)throws Exception{StringBuilder b=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(bytes))b.append(String.format("%02x",v&255));return b.toString();}
 private static UpdateManifest release()throws Exception{Map<String,Object> m=UpdateManifestTest.fixture();m.put("sha256",sha(BYTES));return UpdateManifest.parse(m);}
 private interface Check{void run(UpdateDownloader downloader,File partial,File verified)throws Exception;}
 private void fixture(LocalHttpFixture.Handler handler,Check check)throws Exception{
  try(LocalHttpFixture server=new LocalHttpFixture(handler)){UpdateDownloader downloader=new UpdateDownloader(url->{assertTrue(url.toString().startsWith("https://github.com/"));return(HttpURLConnection)new URL("http://127.0.0.1:"+server.port()+"/apk").openConnection();});check.run(downloader,new File(temp.getRoot(),"candidate.part"),new File(temp.getRoot(),"candidate.apk"));}
 }
 private static final UpdateDownloader.Control CONTROL=new UpdateDownloader.Control(){public boolean cancelled(){return false;}public void progress(long bytes){}public void verifying(){}};
 @Test public void downloadsAndVerifiesBeforeCreatingInstallableFile()throws Exception{fixture(exchange->{exchange.sendResponseHeaders(200,16);exchange.getResponseBody().write(BYTES);exchange.close();},(d,p,v)->{d.download(release(),p,v,CONTROL);assertArrayEquals(BYTES,Files.readAllBytes(v.toPath()));assertFalse(p.exists());});}
 @Test public void resumesOnlyWithTheExpectedContentRange()throws Exception{AtomicReference<String> range=new AtomicReference<>();fixture(exchange->{range.set(exchange.getRequestHeaders().getFirst("Range"));exchange.getResponseHeaders().set("Content-Range","bytes 8-15/16");exchange.sendResponseHeaders(206,8);exchange.getResponseBody().write(BYTES,8,8);exchange.close();},(d,p,v)->{try(FileOutputStream out=new FileOutputStream(p)){out.write(BYTES,0,8);}d.download(release(),p,v,CONTROL);assertEquals("bytes=8-",range.get());assertArrayEquals(BYTES,Files.readAllBytes(v.toPath()));});}
 @Test public void ignoredRangeRestartsFromZeroRatherThanAppending()throws Exception{fixture(exchange->{exchange.sendResponseHeaders(200,16);exchange.getResponseBody().write(BYTES);exchange.close();},(d,p,v)->{try(FileOutputStream out=new FileOutputStream(p)){out.write(BYTES,0,8);}d.download(release(),p,v,CONTROL);assertArrayEquals(BYTES,Files.readAllBytes(v.toPath()));});}
 @Test public void invalidRangeIsDiscardedAndRetriedFromZero()throws Exception{AtomicInteger requests=new AtomicInteger();fixture(exchange->{if(requests.incrementAndGet()==1){exchange.getResponseHeaders().set("Content-Range","bytes 0-7/16");exchange.sendResponseHeaders(206,8);exchange.getResponseBody().write(BYTES,0,8);}else{exchange.sendResponseHeaders(200,16);exchange.getResponseBody().write(BYTES);}exchange.close();},(d,p,v)->{try(FileOutputStream out=new FileOutputStream(p)){out.write(BYTES,0,8);}d.download(release(),p,v,CONTROL);assertEquals(2,requests.get());assertArrayEquals(BYTES,Files.readAllBytes(v.toPath()));});}
 @Test public void wrongHashAndTruncationNeverCreateAnInstallableFile()throws Exception{fixture(exchange->{exchange.sendResponseHeaders(200,16);exchange.getResponseBody().write(BYTES);exchange.close();},(d,p,v)->{try{d.download(UpdateManifest.parse(UpdateManifestTest.fixture()),p,v,CONTROL);fail("corrupt APK accepted");}catch(IOException expected){}assertFalse(v.exists());assertFalse(p.exists());});fixture(exchange->{exchange.sendResponseHeaders(200,16);exchange.getResponseBody().write(BYTES,0,4);exchange.close();},(d,p,v)->{try{d.download(release(),p,v,CONTROL);fail("truncated APK accepted");}catch(IOException expected){}assertFalse(v.exists());});}
 @Test public void unsafeRedirectIsRejectedBeforeOpeningAnotherOrigin()throws Exception{fixture(exchange->{exchange.getResponseHeaders().set("Location","http://127.0.0.1/private");exchange.sendResponseHeaders(302,-1);exchange.close();},(d,p,v)->{try{d.download(release(),p,v,CONTROL);fail("unsafe redirect followed");}catch(IOException expected){}assertFalse(v.exists());});}
 @Test public void cancellationCannotPromoteACompletePartialFile()throws Exception{fixture(exchange->{exchange.sendResponseHeaders(200,16);exchange.getResponseBody().write(BYTES);exchange.close();},(d,p,v)->{final boolean[] stop={false};UpdateDownloader.Control control=new UpdateDownloader.Control(){public boolean cancelled(){return stop[0];}public void progress(long bytes){if(bytes>0)stop[0]=true;}public void verifying(){}};try{d.download(release(),p,v,control);fail("cancelled APK promoted");}catch(IOException expected){}assertFalse(v.exists());});}
 @Test public void corruptedPreviouslyVerifiedCacheIsRejectedBeforeNetworkReuse()throws Exception{AtomicInteger hits=new AtomicInteger();fixture(exchange->{hits.incrementAndGet();exchange.sendResponseHeaders(200,16);exchange.getResponseBody().write(BYTES);exchange.close();},(d,p,v)->{try(FileOutputStream out=new FileOutputStream(v)){out.write("xxxxxxxxxxxxxxxx".getBytes(StandardCharsets.US_ASCII));}try{d.download(release(),p,v,CONTROL);fail("corrupted verified cache silently reused");}catch(UpdateDownloader.InvalidApkException expected){}assertFalse(v.exists());assertEquals(0,hits.get());});}
}
